#!/usr/bin/env node
/*
 * Assert the *built* manifest against the promises the README makes.
 *
 * These cannot be unit-tested: the manifest is generated by crxjs at build time, and the
 * things worth guarding are properties of its output — the host permissions it ends up
 * requesting, and whether the pages it points at were actually emitted. Both fail open
 * and silently. A stray <all_urls> would sail through review; a page that crxjs copied
 * verbatim instead of bundling 404s only when a user clicks it.
 *
 * Run: node scripts/check-manifest.mjs [dist-dir] [--all-hosts]   (after a build)
 *
 * `--all-hosts` checks the `dist-allhosts` variant instead, where one `<all_urls>` pattern
 * is the intended answer rather than a defect. It is not a way to silence the check: the
 * broad pattern becomes *required*, and required to be the only one, so a build that mixes
 * `<all_urls>` with leftover per-domain patterns still fails. Every other assertion —
 * emitted files, bundling, icons, locales — runs identically in both modes.
 */
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

const args = process.argv.slice(2);
const allHosts = args.includes("--all-hosts");
const distName = args.find((arg) => !arg.startsWith("--")) ?? (allHosts ? "dist-allhosts" : "dist");

const dist = join(root, distName);
const manifestPath = join(dist, "manifest.json");

if (!existsSync(manifestPath)) {
  const script = allHosts ? "npm run build:allhosts" : "npm run build";
  console.error(`${distName}/manifest.json not found — run \`${script}\` first.`);
  process.exit(1);
}

const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
const sites = JSON.parse(readFileSync(join(root, "data", "sites.json"), "utf8")).sites;

const errors = [];
const fail = (msg) => errors.push(msg);

// --- host access ----------------------------------------------------------
const BROAD = ["<all_urls>", "*://*/*", "http://*/*", "https://*/*"];
const contentScripts = manifest.content_scripts ?? [];

if (contentScripts.length !== 1) {
  fail(`expected exactly 1 content script, found ${contentScripts.length}`);
}

const actual = new Set(contentScripts[0]?.matches ?? []);

/*
 * `host_permissions` is empty in both builds. The banner needs `content_scripts.matches`,
 * which is a different grant: it lets the injected script touch those pages, but gives the
 * service worker no cross-origin privileges. Nothing here needs those, so a
 * `host_permissions` entry appearing at all is a regression whichever build this is.
 */
for (const pattern of manifest.host_permissions ?? []) {
  fail(`host_permissions requested, which no part of the extension needs: ${pattern}`);
}

/*
 * The two builds go to the store as separate listings, so their name and description must
 * differ. Identical text on two items that differ only in the permission they request is a
 * duplicate submission, and the broader one has nothing to show for the extra access. This
 * is a build-output property — the strings are `__MSG_` keys here and only resolve later —
 * so it is asserted against the keys, and the message-definition check further down proves
 * each key actually exists in _locales.
 */
const NAME_KEY = allHosts ? "__MSG_extNameAllHosts__" : "__MSG_extName__";
const DESCRIPTION_KEY = allHosts ? "__MSG_extDescriptionAllHosts__" : "__MSG_extDescription__";

if (manifest.name !== NAME_KEY) {
  fail(`expected name ${NAME_KEY}, got ${manifest.name}`);
}
if (manifest.description !== DESCRIPTION_KEY) {
  fail(`expected description ${DESCRIPTION_KEY}, got ${manifest.description}`);
}

if (allHosts) {
  /*
   * The variant's whole purpose is that its host scope is a constant — one pattern that no
   * release can change, so no update is ever a privilege increase. A build that widened to
   * `<all_urls>` *and* kept the generated per-domain patterns would have the broad install
   * warning and the changing permission set: the cost of both designs, the benefit of
   * neither. So the pattern set must be exactly the one.
   */
  if (actual.size !== 1 || !actual.has("<all_urls>")) {
    fail(`expected content_scripts.matches to be exactly ["<all_urls>"], got ${[...actual].join(", ")}`);
  }
} else {
  for (const pattern of actual) {
    if (BROAD.includes(pattern)) fail(`broad host access requested: ${pattern}`);
  }

  // Two patterns per domain: the bare domain and its subdomains.
  const expected = new Set(
    sites.flatMap((site) => {
      const d = site.domain.trim().toLowerCase().replace(/^www\./, "");
      return [`*://${d}/*`, `*://*.${d}/*`];
    }),
  );
  for (const pattern of expected) {
    if (!actual.has(pattern)) fail(`dataset domain missing from matches: ${pattern}`);
  }
  for (const pattern of actual) {
    if (!expected.has(pattern)) fail(`matches pattern not backed by the dataset: ${pattern}`);
  }
}

/*
 * Whatever a web page can reach has to match where the content script runs — no wider, and
 * no narrower. Wider hands the proof page to sites the extension has nothing to say about;
 * narrower gives the banner a "source" link that resolves nowhere on some of the very
 * pages it appears on.
 */
for (const entry of manifest.web_accessible_resources ?? []) {
  for (const pattern of entry.matches ?? []) {
    if (!actual.has(pattern)) {
      fail(
        `web_accessible_resources exposed to ${pattern}, which the content script does ` +
          `not run on: ${entry.resources?.join(", ")}`,
      );
    }
  }
}

// --- referenced files exist and were bundled ------------------------------
const referenced = [
  manifest.action?.default_popup,
  manifest.options_page,
  manifest.background?.service_worker,
  ...contentScripts.flatMap((cs) => [...(cs.js ?? []), ...(cs.css ?? [])]),
  ...(manifest.web_accessible_resources ?? []).flatMap((e) => e.resources ?? []),
].filter((path) => path && !path.includes("*"));

for (const path of referenced) {
  if (!existsSync(join(dist, path))) fail(`manifest references a missing file: ${path}`);
}

/*
 * A crxjs page that was copied rather than treated as an entry point still points at its
 * TypeScript source, which does not exist in dist/. The build reports success either way.
 */
for (const path of referenced.filter((p) => p.endsWith(".html"))) {
  const html = readFileSync(join(dist, path), "utf8");
  const unbundled = [...html.matchAll(/<script[^>]+src="([^"]+\.ts)"/g)].map((m) => m[1]);
  for (const src of unbundled) {
    fail(`${path} was not bundled — it still references ${src}`);
  }
}

/*
 * Carried over from test/data.test.js, which asserted these against the hand-written
 * manifest.json. That file is generated now, so the assertions belong here.
 */
if (manifest.manifest_version !== 3) fail(`manifest_version is ${manifest.manifest_version}, expected 3`);
if (!/^\d+\.\d+\.\d+$/.test(manifest.version ?? "")) {
  fail(`version is not semver-ish: ${manifest.version}`);
}
for (const size of ["16", "32", "48", "128"]) {
  if (!manifest.icons?.[size]) fail(`missing icon size ${size}`);
  if (!manifest.action?.default_icon?.[size]) fail(`missing action icon size ${size}`);
}

// --- localization ---------------------------------------------------------
if (manifest.default_locale) {
  const messages = join(dist, "_locales", manifest.default_locale, "messages.json");
  if (!existsSync(messages)) {
    fail(`default_locale is "${manifest.default_locale}" but ${messages} is missing`);
  } else {
    const defined = JSON.parse(readFileSync(messages, "utf8"));
    const used = [...JSON.stringify(manifest).matchAll(/__MSG_(\w+)__/g)].map((m) => m[1]);
    for (const key of used) {
      if (!(key in defined)) fail(`manifest uses __MSG_${key}__ with no message defined`);
    }
  }
}

if (errors.length > 0) {
  console.error(`\n${distName}/manifest.json failed ${errors.length} check(s):`);
  for (const e of errors) console.error(`  ✗ ${e}`);
  process.exit(1);
}

console.log(
  `${distName}/manifest.json OK — ` +
    (allHosts
      ? "one <all_urls> match pattern, a host scope no release can change"
      : `${actual.size} scoped match patterns, no broad host access`) +
    `, ${referenced.length} referenced files present.`,
);
